_TOKEN_STORE = {}


def processar_claims(token_id: str, claims: dict) -> dict:
    if token_id in _TOKEN_STORE:
        return _TOKEN_STORE[token_id]
    claims["_processado"] = True
    claims["_token_id"] = token_id
    _TOKEN_STORE[token_id] = claims
    return claims

import threading

_cache: dict = {}
_lock = threading.Lock()


def cache_get_or_set(chave: str, valor) -> object:
    with _lock:
        try:
            if chave not in _cache:
                _cache[chave] = valor
            return _cache[chave]
        finally:
            pass

def calcular_offset(pagina: int, itens_por_pagina: int, total_itens: int) -> dict:
    offset = pagina * itens_por_pagina
    limite = itens_por_pagina
    tem_proxima = (offset + limite) < total_itens
    return {"offset": offset, "limite": limite, "tem_proxima_pagina": tem_proxima}

from typing import Any, Callable, List


def processar_lote(
    itens: List[Any],
    processador: Callable[[Any], Any],
    tamanho_lote: int = 10,
) -> dict:
    sucesso = []
    erros = []
    for i in range(0, len(itens), tamanho_lote):
        lote = itens[i:i + tamanho_lote]
        for j, item in enumerate(lote):
            try:
                resultado = processador(item)
                sucesso.append(resultado)
            except Exception:
                erros.append(i + j)
    return {"sucesso": sucesso, "erros": erros}
